window.MG_LAZY_DATA["data/lazy/resources/soft-v29-064-f9963f4b6cdc5ae9.json"]={sha256:"f9963f4b6cdc5ae94c8c391b2c38c9a2b3fe1e8decf764455bc70392417e4855",value:{"sources":[{"id":"v29-case-51aca5cd42fa1909","url":"https://unicode-org.github.io/icu/userguide/format_parse/numbers/","title":"ICU CLDR: locale formatting and language fallback — primary reference","titleEn":"ICU CLDR: locale formatting and language fallback — primary reference","publisher":"Original project / standard / author","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"soft-v29-064","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"soft-v29-064","related":[{"id":"soft-v29-065","referenceUrls":["https://www.rfc-editor.org/rfc/rfc8259"],"title":"JSON：型別、重複鍵與數值界線","titleEn":"JSON: types, duplicate names and numeric boundaries","why":"用兩課的可觀察驗收條件比較模型邊界：研究5驗收：交付locale-matrix.csv及回退政策，註明locale偏好不等於精確所在地。 請保留本研究的輸入、逐筆中間狀態與不符合條件時的處置。","whyEn":"Compare model boundaries using observable acceptance criteria: Investigation 5 acceptance: Deliver locale-matrix.csv and fallback policy, noting that locale preferences do not reveal exact location. Retain inputs, intermediate state and the disposition when the criterion is not met.","difference":"定義ID以字串傳、量測值以number傳；用object_pairs_hook拒絕重複名稱，拒絕NaN與Infinity擴充。","differenceEn":"Encode IDs as strings and measurements as numbers; reject duplicate names with object_pairs_hook and disallow NaN/Infinity extensions.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["locale同時含語言及地區偏好；格式化字串不應再當無地區資訊的數值解析。回退鏈須可見且可由使用者覆寫。\n本課數值核對：10.5+20+30.25 = 60.75 currency_units；另一項核對：1234.5*100 = 123450 minor_units。兩項若屬不同量綱，不得直接相除或相減。","JSON number語法與接收端數值表示能力不同；重複object名稱的處理可能不一致，交換契約應明確拒絕或規定。\n本課數值核對：2**53-1 = 9007199254740991 integer；另一項核對：2**53 = 9007199254740992 integer。兩項若屬不同量綱，不得直接相除或相減。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["A locale combines language and regional conventions; formatted strings should not be parsed without locale context. Fallback chains should be visible and user-overridable.\nNumeric audit: 10.5+20+30.25 = 60.75 currency_units; second audit: 1234.5*100 = 123450 minor_units. Quantities with different dimensions must not be directly divided or subtracted.","JSON number syntax differs from a receiver’s numeric capacity; duplicate object-name handling varies, so interchange contracts should reject or explicitly define it.\nNumeric audit: 2**53-1 = 9007199254740991 integer; second audit: 2**53 = 9007199254740992 integer. Quantities with different dimensions must not be directly divided or subtracted.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"soft-v29-074","referenceUrls":["https://www.sqlite.org/lang_createtable.html"],"title":"關聯正規化：訂單功能相依與無損分解","titleEn":"Relational normalization: dependencies and lossless decomposition","why":"用兩課的可觀察驗收條件比較模型邊界：研究5驗收：交付locale-matrix.csv及回退政策，註明locale偏好不等於精確所在地。 請保留本研究的輸入、逐筆中間狀態與不符合條件時的處置。","whyEn":"Compare model boundaries using observable acceptance criteria: Investigation 5 acceptance: Deliver locale-matrix.csv and fallback policy, noting that locale preferences do not reveal exact location. Retain inputs, intermediate state and the disposition when the criterion is not met.","difference":"從重複顧客地址的訂單表找出更新異常，再以鍵驗證分解。","differenceEn":"Find update anomalies in orders repeating customer addresses, then validate decomposition using keys.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["locale同時含語言及地區偏好；格式化字串不應再當無地區資訊的數值解析。回退鏈須可見且可由使用者覆寫。\n本課數值核對：10.5+20+30.25 = 60.75 currency_units；另一項核對：1234.5*100 = 123450 minor_units。兩項若屬不同量綱，不得直接相除或相減。","顧客 ID 決定地址，訂單 ID 決定顧客；把不同實體的相依混在一起會產生修改不一致。 教學基準：7*80 = 560 duplicated address bytes；第二檢核：2*80 = 160 normalized address bytes。逐項保留單位、分母、排序或時間界線。 先手算或逐事件枚舉，再使用SQL、試算表或本機腳本重算，保存中間狀態。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["A locale combines language and regional conventions; formatted strings should not be parsed without locale context. Fallback chains should be visible and user-overridable.\nNumeric audit: 10.5+20+30.25 = 60.75 currency_units; second audit: 1234.5*100 = 123450 minor_units. Quantities with different dimensions must not be directly divided or subtracted.","Customer ID determines address and order ID determines customer; mixing dependencies creates update inconsistencies. Teaching baseline: 7*80 = 560 duplicated address bytes; second check: 2*80 = 160 normalized address bytes. Retain units,denominators,ordering and time boundaries. Enumerate by hand before using SQL,a spreadsheet or a local script; preserve intermediate states.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v29-case-4d089713c1e8d684","url":"https://www.rfc-editor.org/rfc/rfc8259","title":"JSON: types, duplicate names and numeric boundaries — primary reference","titleEn":"JSON: types, duplicate names and numeric boundaries — primary reference","publisher":"Original project / standard / author","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v29-case-9dc4dc666cbaa7c7","url":"https://www.sqlite.org/lang_createtable.html","title":"SQLite CREATE TABLE","titleEn":"SQLite CREATE TABLE","publisher":"SQLite","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
